// Generated by tour2playwright from a Tour Recorder export, then hand-edited.
// Source tour: Finance: Customer Follow-up Reports ( Levels - Review - Send ) - Full Flow
// Hand edits: ids/text instead of positions, state assertions, result screenshots, wide viewport, login fallback.
// SAFETY: steps 1-28 create three follow-up levels (tagged [TEST]). Steps 29-46 only LOOK at real customers:
// they never change a customer, never press Send and never run "Process Automatic Follow-ups".
import { test, expect } from "../../../../core/fixtures/index";
import { uniqueName } from "../../../../core/utils/RandomDataGenerator";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/finance-customer-follow-up-reports-levels-review-send-full-flow";

// A step's own screenshot is taken BEFORE its action; this keeps one of the finished screen.
async function resultShot(page: Page, n: number) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/step-${String(n).padStart(2, "0")}-result.png` });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

const L1 = uniqueName("1st Reminder - Email");
const L2 = uniqueName("2nd Reminder - Letter");
const L3 = uniqueName("Final Notice - SMS + Call");

// The recorded ladder (15 / 30 / 60 days) already exists on the test database and Odoo allows each number of days
// only once per company, so the test uses clearly-test-only delays and removes its own levels afterwards.
test.afterEach(async ({ rpc }) => {
  const ids = await rpc.searchRead<{ id: number }>("account_followup.followup.line", [["name", "like", "[TEST]"]], ["id"]);
  if (ids.length) await rpc.unlink("account_followup.followup.line", ids.map((r) => r.id));
});

test.describe("Finance: Customer Follow-up Reports ( Levels - Review - Send ) - Full Flow @module:accounting @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  test("Finance: Customer Follow-up Reports ( Levels - Review - Send ) - Full Flow", async ({ page }) => {
    test.setTimeout(240_000);
    await page.goto("/web");

    // The saved browser session can expire — fall back to the login form if we got bounced to it.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});

    // Shared step runner: wait for the target, take the outlined screenshot, then act.
    const run = async (n: number, title: string, loc: Locator, act?: (l: Locator) => Promise<void>, result = false) => {
      await test.step(`${String(n).padStart(2, "0")}. ${title}`, async () => {
        const l = loc.first();
        await l.waitFor({ state: "visible", timeout: 45000 });
        await shot(page, l, `step-${String(n).padStart(2, "0")}.png`);
        if (act) await act(l);
        if (result) await resultShot(page, n);
      });
    };
    const menu = (xmlid: string) => page.locator(`[data-menu-xmlid="${xmlid}"]`);
    const ensureChecked = async (l: Locator) => { if (!(await l.isChecked())) await l.check(); await expect(l).toBeChecked(); };
    const field = (name: string) => page.locator(`.o_field_widget[name="${name}"]`);
    const newBtn = page.getByRole("button", { name: "New", exact: true });
    // Ticking Schedule Activity makes Activity Type and Summary required — fill them or the stage cannot be saved.
    const fillActivity = async (summary: string) => {
      const type = page.locator("#activity_type_id_0");
      await type.fill("Call");
      const opt = page.locator(".o-autocomplete--dropdown-item").filter({ hasText: /^Call$/ }).first();
      await opt.waitFor({ state: "visible", timeout: 15000 });
      await opt.click();
      await expect(type, "activity type chosen").toHaveValue(/Call/i);
      const sum = page.getByLabel("Summary", { exact: true }).first();
      await sum.fill(summary);
      await expect(sum).toHaveValue(summary);
    };
    // A customer without an email address makes Odoo open an "Edit: <customer>" dialog on top of the wizard —
    // discard it (nothing is saved on the customer).
    const dismissEdit = async () => {
      const edit = page.locator(".modal").filter({ has: page.locator(".modal-title", { hasText: /Edit:/ }) });
      if (await edit.first().isVisible({ timeout: 4000 }).catch(() => false)) {
        await edit.first().getByRole("button", { name: "Discard" }).click();
        await expect(edit).toHaveCount(0, { timeout: 10000 });
      }
    };
    const save = async () => {
      await page.locator("button.o_form_button_save").click();
      await expect(page.locator("button.o_form_button_save"), "level saved").toBeHidden({ timeout: 30000 });
    };

    // ---------------------------------------------------------------- Part 1: configure the levels
    await run(1, "Open Accounting app", menu("account_accountant.menu_accounting"), (l) => l.click());
    await run(2, "Open the Configuration menu", menu("account.menu_finance_configuration"), (l) => l.click());
    await run(3, "Open Follow-up Levels", menu("account_followup.account_followup_menu"), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "Follow-up Levels list opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(4, "Create a new follow-up level", newBtn, async (l) => {
      await l.click();
      await expect(page.locator(".o_form_view"), "new level form opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(5, "Name the first stage", page.locator("#name_0"), async (l) => { await l.fill(L1); await expect(l).toHaveValue(L1); }, true);
    await run(6, "Set the delay in days", page.locator("#delay_0"), async (l) => { await l.fill("115"); await l.press("Tab"); await expect(l).toHaveValue("115"); }, true);
    await run(7, "Actions: what the stage does", page.locator("#send_email_0"), async (l) => { await ensureChecked(l); }, true);
    await run(8, "Content Template (optional)", page.locator("#mail_template_id_0"), async (l) => { await expect(l).toBeVisible(); });
    await run(9, "Tick Automatic", page.locator("#auto_execute_0"), ensureChecked, true);
    await run(10, "Attach Invoices", page.locator("#join_invoices_0"), ensureChecked, true);
    await run(11, "Open the Activity tab", page.locator('a[name="activity"]'), async (l) => {
      await l.click();
      await expect(page.locator("#create_activity_0"), "Activity tab opened").toBeVisible();
    }, true);
    await run(12, "Schedule Activity (optional)", page.locator("#create_activity_0"), async (l) => { await ensureChecked(l); await fillActivity("Review overdue balance"); }, true);
    await run(13, "Save the first stage", page.locator("button.o_form_button_save"), async (l) => {
      await l.click();
      await expect(page.locator("button.o_form_button_save"), "stage 1 saved").toBeHidden({ timeout: 30000 });
    }, true);

    await run(14, "Add the second stage", newBtn, async (l) => { await l.click(); await expect(page.locator("#name_0")).toHaveValue("", { timeout: 30000 }); }, true);
    await run(15, "Name the second stage", page.locator("#name_0"), async (l) => { await l.fill(L2); await expect(l).toHaveValue(L2); }, true);
    await run(16, "Set the second delay", page.locator("#delay_0"), async (l) => { await l.fill("130"); await l.press("Tab"); await expect(l).toHaveValue("130"); }, true);
    await run(17, "Back to the Notification tab", page.locator('a[name="notification"]'), async (l) => {
      await l.click();
      await expect(page.locator("#send_letter_0"), "Notification tab opened").toBeVisible();
    }, true);
    await run(18, "Tick Send a Letter", page.locator("#send_letter_0"), ensureChecked, true);
    await run(19, "Save the second stage", page.locator("button.o_form_button_save"), async (l) => {
      await l.click();
      await expect(page.locator("button.o_form_button_save"), "stage 2 saved").toBeHidden({ timeout: 30000 });
    }, true);

    await run(20, "Add the final stage", newBtn, async (l) => { await l.click(); await expect(page.locator("#name_0")).toHaveValue("", { timeout: 30000 }); }, true);
    await run(21, "Name the final stage", page.locator("#name_0"), async (l) => { await l.fill(L3); await expect(l).toHaveValue(L3); }, true);
    await run(22, "Set the final delay", page.locator("#delay_0"), async (l) => { await l.fill("160"); await l.press("Tab"); await expect(l).toHaveValue("160"); }, true);
    await run(23, "Tick Send SMS Message", page.locator("#send_sms_0"), ensureChecked, true);
    await run(24, "Open the Activity tab", page.locator('a[name="activity"]'), async (l) => {
      await l.click();
      await expect(page.locator("#create_activity_0"), "Activity tab opened").toBeVisible();
    }, true);
    await run(25, "Tick Schedule Activity", page.locator("#create_activity_0"), ensureChecked, true);
    await run(26, "Choose the Activity Type", page.locator("#activity_type_id_0"), async () => { await fillActivity("Call customer - final notice"); }, true);
    await run(27, "Save the final stage", page.locator("button.o_form_button_save"), async (l) => {
      await l.click();
      await expect(page.locator("button.o_form_button_save"), "final stage saved").toBeHidden({ timeout: 30000 });
    }, true);

    await run(28, "Review the three stages", page.locator(".o_breadcrumb .breadcrumb-item").filter({ hasText: "Follow-up Levels" }), async (l) => {
      await l.click();
      for (const name of [L1, L2, L3]) {
        await expect(page.locator(".o_list_view"), "level in the list: " + name).toContainText(name, { timeout: 30000 });
      }
    }, true);

    // ---------------------------------------------------------------- Part 2: the daily routine (read-only)
    await run(29, "Open the Customers menu", page.locator(".o_menu_sections .dropdown-toggle, .o_menu_sections a").filter({ hasText: /^Customers$/ }), async (l) => {
      await l.click();
      await expect(page.locator(".dropdown-item").filter({ hasText: "Follow-up Reports" }).first()).toBeVisible();
    }, true);
    await run(30, "Open Follow-up Reports", page.locator(".dropdown-item").filter({ hasText: "Follow-up Reports" }), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "Follow-up Reports list opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(31, "Read the worklist", page.locator('th[data-name="followup_status"]'), async (l) => {
      await expect(l).toBeVisible();
      await expect(page.locator("thead"), "Follow-up Level column").toContainText("Follow-up Level");
    });

    let hasCustomer = true;
    await test.step("32. Open a customer's follow-up", async () => {
      // The tour uses "Test Credit Customer"; fall back to the first line if it is not on the list.
      const named = page.locator(".o_data_row").filter({ hasText: "Test Credit Customer" });
      const row = (await named.count()) ? named.first() : page.locator(".o_data_row").first();
      hasCustomer = await row.isVisible({ timeout: 15000 }).catch(() => false);
      if (!hasCustomer) { await shot(page, page.locator(".o_list_view"), "step-32.png"); return; }
      const loc = row.locator('td[name="name"]');
      await shot(page, loc, "step-32.png");
      await loc.click();
      await expect(page.locator(".o_form_view"), "customer follow-up opened").toBeVisible({ timeout: 30000 });
      await resultShot(page, 32);
    });

    if (hasCustomer) {
      // Steps 33-40: look only. Nothing is clicked or changed on the customer.
      const lookAt = async (n: number, title: string, sel: string) => run(n, title, page.locator(sel), async (l) => { await expect(l).toBeVisible(); });
      await lookAt(33, "The stage bar", "div.o_statusbar_status");
      await lookAt(34, "Exclude a line from follow-ups", 'th[data-name="blocked"]');
      await lookAt(35, "Automatic or Manual reminders", ".o_field_widget[name='manual_followup'], .o_form_view input[type=radio]");
      await lookAt(36, "Next reminder date", "#followup_next_action_date_0");
      await run(37, "Click Follow up to send", page.getByRole("button", { name: /^Follow.?up$/ }), async (l) => {
        await l.click();
        await expect(page.locator(".modal").filter({ hasText: "Send and Print" }), "Send and Print wizard opened").toBeVisible({ timeout: 30000 });
        await dismissEdit();
      }, true);
      await dismissEdit();
      await lookAt(38, "Choose the send channels", ".modal #email_0");
      await lookAt(39, "Check the message body", ".modal .o_form_renderer");
      await lookAt(40, "Attach the invoices", ".modal #join_invoices_0");
      // Step 41 only points at the Send button — it is NOT pressed.
      await run(41, "The Send button", page.locator(".modal-footer button").filter({ hasText: /^Send/ }), async (l) => { await expect(l).toBeVisible(); });
      await dismissEdit();
      await run(42, "Close the wizard", page.locator(".modal-footer button").filter({ hasText: /^Cancel$/ }), async (l) => {
        await l.click();
        await expect(page.locator(".modal"), "wizard closed without sending").toBeHidden({ timeout: 15000 });
      }, true);
      await run(43, "Back to the worklist", page.locator(".o_breadcrumb .breadcrumb-item").filter({ hasText: "Follow-up Reports" }), async (l) => {
        await l.click();
        await expect(page.locator(".o_list_view")).toBeVisible({ timeout: 30000 });
      }, true);
      await run(44, "Select customers for a batch", page.locator("thead .o_list_record_selector input"), async (l) => {
        await l.check();
        await expect(page.locator(".o_cp_action_menus, .o_control_panel").filter({ hasText: /selected/i }).first()).toBeVisible({ timeout: 15000 });
      }, true);
      await run(45, "Open the Actions menu", page.locator(".o_cp_action_menus button").filter({ hasText: /Actions/ }), async (l) => {
        await l.click();
        await expect(page.locator(".dropdown-menu").filter({ hasText: /Process Automatic Follow/ })).toBeVisible();
      }, true);
      // Step 46 only points at the item — it is NOT clicked (it would send real reminders to the selected customers).
      await run(46, "Process Automatic Follow-ups", page.locator(".dropdown-item").filter({ hasText: /Process Automatic Follow/ }), async (l) => { await expect(l).toBeVisible(); });
    }
  });
});
